33	@Service
34	public class RollupService {
35	
36	    /** Shown in place of a due-total whose grade has no rate. */
37	    private static final String NO_RATE = "n/a";
38	
39	    /** A person's figures, as the screen shows them. */
40	    public record Figures(String name, String claimed, String dueTotal) {}
