81	    public Snapshot snapshot(String sheetId) {
82	        Lateness late = latenessOf(sheetId);
83	        LocalDate today = late.today();
84	        BigDecimal floor = floorOf(sheetId);
85	        Map<Long, List<Claim>> byPerson = new LinkedHashMap<>();
86	        List<Claim> all = claims.findBySheetIdOrderByIdDesc(sheetId);
87	        for (Claim claim : all) {
88	            byPerson.computeIfAbsent(claim.getPersonId(), k -> new ArrayList<>()).add(claim);
89	        }
