95	        for (Person person : people.findBySheetIdOrderByIdAsc(sheetId)) {
96	            List<Claim> counted = byPerson.getOrDefault(person.getId(), List.of()).stream()
97	                    .filter(c -> counts(c, person)).toList();
98	            BigDecimal claimed = BigDecimal.ZERO.setScale(2);
99	            BigDecimal due = BigDecimal.ZERO.setScale(2);
