123	    /** The due-total of the sheet's claims that count (OPEN and PENDING ones within a hold, unbound, do not) dated from and to, inclusive: the sum of their dues,
124	     * late charges included, n/a ones skipped. */
125	    public BigDecimal dueTotal(String sheetId, LocalDate from, LocalDate to) {
126	        BigDecimal floor = floorOf(sheetId);
127	        Lateness late = latenessOf(sheetId);
128	        Map<String, List<Rate>> byGrade = ratesByGrade(sheetId);
129	        Map<Long, Person> byId = new LinkedHashMap<>();
130	        for (Person person : people.findBySheetIdOrderByIdAsc(sheetId)) {
