223	    private static boolean rated(Person person, List<Claim> counted, LocalDate today,
224	            Map<String, List<Rate>> byGrade) {
225	        if (today == null) {
226	            return false;
227	        }
228	        Set<String> grades = new HashSet<>();
229	        grades.add(person.gradeOn(today));
230	        for (Claim claim : counted) {
