239	    }
240	
241	    /** The rates of the grade a person has on a date. */
242	    private static List<Rate> ratesOn(Person person, LocalDate date, Map<String, List<Rate>> byGrade) {
243	        return byGrade.getOrDefault(person.gradeOn(date), List.of());
244	    }
