246	    /** The sheet's rates by grade. */
247	    private Map<String, List<Rate>> ratesByGrade(String sheetId) {
248	        Map<String, List<Rate>> by = new HashMap<>();
249	        for (Rate rate : rates.findBySheetId(sheetId)) {
250	            by.computeIfAbsent(rate.getGrade(), k -> new ArrayList<>()).add(rate);
251	        }
