255	    private static BigDecimal dueOf(Claim claim, List<Rate> gradeRates, BigDecimal floor, Lateness late,
256	            LocalDate roundsBy) {
257	        RoundingMode rounding = late.rounding(roundsBy);
258	        BigDecimal figure = figureOf(claim, gradeRates, floor, rounding);
259	        return figure == null ? null : figure.add(lateCharge(claim, figure, late, rounding));
260	    }
261	
262	    /**
263	     * The late charge on a claim: the late percent of its figure for every full 30 days it is overdue (OPEN or
264	     * PENDING, and its due-by, fixed when it was added, before the sheet's today), rounded to two decimals as the claim rounds.
265	     * A statement never binds it: it follows the sheet's today. A correction has none.
266	     */
267	    private static BigDecimal lateCharge(Claim claim, BigDecimal figure, Lateness late, RoundingMode rounding) {
268	        if (!claim.getStatus().isOpen() || late.today() == null || claim.isCorrection()) {
269	            return BigDecimal.ZERO.setScale(2);
270	        }
271	        long overdueDays = ChronoUnit.DAYS.between(claim.getDueBy(), late.today());
272	        long periods = overdueDays > 0 ? overdueDays / LATE_PERIOD_DAYS : 0;
273	        return figure.multiply(late.latePct()).multiply(BigDecimal.valueOf(periods))
274	                .divide(BigDecimal.valueOf(100), 2, rounding);
275	    }
276	
277	    private static BigDecimal figureOf(Claim claim, List<Rate> gradeRates, BigDecimal floor, RoundingMode rounding) {
278	        if (claim.getSettledDue() != null) {
279	            return claim.getSettledDue();
280	        }
281	        return bound(claim) ? claim.getStatedDue() : liveDueOf(claim, gradeRates, floor, rounding);
282	    }
283	
284	    /** What is due on a claim at the rate its grade has in force on the claim's date, rounded to two decimals as
285	     * the claim rounds, and at least the floor (a correction has no floor); none when no rate of the grade applies
286	     * then. */
287	    private static BigDecimal liveDueOf(Claim claim, List<Rate> gradeRates, BigDecimal floor, RoundingMode rounding) {
288	        BigDecimal amount = claim.getAmount();
289	        return Rate.inForce(gradeRates, claim.getDate())
290	                .map(r -> amount.multiply(r.getRate()).divide(BigDecimal.valueOf(100), 2, rounding))
291	                .map(due -> claim.isCorrection() ? due : due.max(floor.setScale(2)))
292	                .orElse(null);
293	    }
294	
295	    private Lateness latenessOf(String sheetId) {
296	        return Lateness.of(sheets.findById(sheetId).orElse(null));
297	    }
298	
299	    /** The sheet's floor; 1.00, the one a sheet starts with, when there is no such sheet. */
300	    private BigDecimal floorOf(String sheetId) {
301	        return sheets.findById(sheetId).map(s -> s.getFloor()).orElse(new BigDecimal("1.00"));
302	    }
303	
304	    /** Whether a claim goes by the figure its person's last statement bound it to: a PENDING claim is not bound,
305	     * but shows its live figure, and is bound again if it is rejected. */
306	    private static boolean bound(Claim claim) {
307	        return claim.isStated() && claim.getStatus() != ClaimStatus.PENDING;
308	    }
309	
310	    /** Only OPEN, PENDING and SETTLED claims count toward what is claimed and due; an OPEN or PENDING one dated
