267	  protected readonly settings = signal<SheetSettings>(NO_SETTINGS);
268	  protected readonly roleError = signal<string | null>(null);
269	  protected readonly settingsError = signal<string | null>(null);
270	  private readonly busy = signal(false);
271	  /** The setting a person went into last; the clerk limit until they go into one. */
272	  private lastField: keyof SettingsFormValue = 'clerkLimit';
273	  /** Settings saves, sent one after another in the order they were made, so none is lost while another is
274	   * waiting on the server. */
275	  private readonly saves = new Subject<{ sheetId: string; changed: Parameters<SettingsApi['save']>[1]; sent: SettingsFormValue }>();
276	  protected readonly roleForm = new FormGroup({
277	    user: new FormControl('', { nonNullable: true }),
278	    role: new FormControl('', { nonNullable: true }),
279	  });
280	  protected readonly settingsForm = new FormGroup({
281	    clerkLimit: new FormControl('', { nonNullable: true }),
282	    floor: new FormControl(DEFAULT_FLOOR, { nonNullable: true }),
283	    terms: new FormControl(String(DEFAULT_TERMS), { nonNullable: true }),
284	    termsA: new FormControl('', { nonNullable: true }),
285	    termsB: new FormControl('', { nonNullable: true }),
286	    termsC: new FormControl('', { nonNullable: true }),
287	    latePct: new FormControl(DEFAULT_LATE_PCT, { nonNullable: true }),
288	    policyDate: new FormControl('', { nonNullable: true }),
289	    periodNumberingFrom: new FormControl('', { nonNullable: true }),
