292	  constructor() {
293	    this.roleForm.valueChanges.subscribe(() => this.roleError.set(null));
294	    this.settingsForm.valueChanges.subscribe(() => this.settingsError.set(null));
295	    this.saves
296	      .pipe(
297	        concatMap(({ sheetId, changed, sent }) =>
298	          this.api.save(sheetId, changed).pipe(
299	            map((s) => ({ sheetId, sent, s })),
300	            catchError(() => of({ sheetId, sent, s: null })),
301	          ),
302	        ),
303	      )
304	      .subscribe(({ sheetId, sent, s }) => {
305	        if (s === null) {
306	          this.settingsError.set('Could not save the settings.');
307	        } else if (this.session.sheetId() === sheetId) {
308	          this.showSettings(s, sent);
309	        }
310	      });
311	    // Re-read the sheet's settings from the store each time a sheet is loaded.
312	    const loaded = this.session.registerLoader(inject(DestroyRef));
313	    toObservable(this.session.sheetId)
314	      .pipe(
315	        switchMap((id) =>
316	          id
317	            ? forkJoin({ id: of(id), roles: this.api.roles(id), settings: this.api.get(id) })
318	            : of({ id, roles: [] as RoleGiven[], settings: NO_SETTINGS }),
319	        ),
320	      )
321	      .subscribe(({ id, roles, settings }) => {
322	        this.roles.set(roles);
323	        this.showSettings(settings);
324	        this.roleError.set(null);
325	        this.settingsError.set(null);
326	        loaded(id);
327	      });
328	  }
