330	  protected setRole(): void {
331	    if (this.busy()) return;
332	    this.roleError.set(null);
333	    const sheetId = this.session.sheetId();
334	    if (!sheetId) {
335	      this.roleError.set('Load a sheet first.');
336	      return;
337	    }
338	    const user = this.roleForm.getRawValue().user.trim();
339	    const role = this.roleForm.getRawValue().role.trim();
340	    if (!user) {
341	      this.roleError.set('Type a user name.');
342	      return;
343	    }
344	    if (!(ROLES as readonly string[]).includes(role)) {
345	      this.roleError.set(`A role is ${this.roleNames}.`);
346	      return;
347	    }
348	    this.busy.set(true);
349	    this.api.setRole(sheetId, user, role).subscribe({
