372	  /** Note the setting a person went into last: a save with nothing changed saves that one again. */
373	  protected focused(event: FocusEvent): void {
374	    const name = (event.target as Element | null)?.getAttribute('formcontrolname');
375	    if (name && name in this.settingsForm.controls) this.lastField = name as keyof SettingsFormValue;
376	  }
