378	  protected save(): void {
379	    this.settingsError.set(null);
380	    const sheetId = this.session.sheetId();
381	    if (!sheetId) {
382	      this.settingsError.set('Load a sheet first.');
383	      return;
384	    }
385	    const controls = this.settingsForm.controls;
386	    // With nothing changed, the setting last gone into is saved again as it is.
387	    const unchanged = !this.settingsForm.dirty;
388	    const send = (key: keyof SettingsFormValue) => controls[key].dirty || (unchanged && this.lastField === key);
389	    const clerkLimit = controls.clerkLimit.value.trim();
390	    const floor = controls.floor.value.trim();
391	    const terms = controls.terms.value.trim();
392	    const sendFloor = send('floor');
393	    const latePct = controls.latePct.value.trim();
394	    const sendTerms = send('terms');
395	    const sendLatePct = send('latePct');
396	    const policyDate = controls.policyDate.value.trim();
397	    const sendPolicyDate = send('policyDate');
398	    const periodNumberingFrom = controls.periodNumberingFrom.value.trim();
399	    const sendPeriodNumbering = send('periodNumberingFrom');
400	    const sendLimit = send('clerkLimit');
401	    if (sendLimit && clerkLimit !== '' && !LIMIT.test(clerkLimit)) {
402	      this.settingsError.set('Type a clerk limit of 0.00 or more, with up to two decimals, or leave it blank.');
403	      return;
404	    }
405	    if (sendFloor && !LIMIT.test(floor)) {
406	      this.settingsError.set('Type a floor of 0.00 or more, with up to two decimals.');
407	      return;
408	    }
409	    if (sendTerms && !DAYS.test(terms)) {
410	      this.settingsError.set('Type terms of 0 or more whole days.');
411	      return;
412	    }
413	    const gradeTerms: Partial<Record<GradeTermsKey, string>> = {};
414	    for (const g of GRADES) {
415	      const key = this.gradeKey(g);
416	      if (!send(key)) continue;
417	      const days = controls[key].value.trim();
418	      if (days !== '' && !DAYS.test(days)) {
419	        this.settingsError.set(`Type terms for grade ${g} of 0 or more whole days, or leave them blank.`);
420	        return;
421	      }
422	      gradeTerms[key] = days;
423	    }
424	    if (sendLatePct && !PCT.test(latePct)) {
425	      this.settingsError.set('Type a late percent of 0.00 or more, with up to two decimals.');
426	      return;
427	    }
428	    if (sendPolicyDate && policyDate !== '' && !(DATE.test(policyDate) && !isNaN(Date.parse(policyDate)))) {
429	      this.settingsError.set('Type a policy date as yyyy-mm-dd, or leave it blank.');
430	      return;
431	    }
432	    if (
433	      sendPeriodNumbering &&
434	      periodNumberingFrom !== '' &&
435	      !(DATE.test(periodNumberingFrom) && !isNaN(Date.parse(periodNumberingFrom)))
436	    ) {
437	      this.settingsError.set('Type a period numbering date as yyyy-mm-dd, or leave it blank.');
438	      return;
439	    }
440	    const changed = {
441	      ...(sendLimit ? { clerkLimit } : {}),
442	      ...(sendFloor ? { floor } : {}),
443	      ...(sendTerms ? { terms } : {}),
444	      ...gradeTerms,
445	      ...(sendLatePct ? { latePct } : {}),
446	      ...(sendPolicyDate ? { policyDate } : {}),
447	      ...(sendPeriodNumbering ? { periodNumberingFrom } : {}),
448	    };
449	    this.saves.next({ sheetId, changed, sent: this.settingsForm.getRawValue() });
450	  }
