452	  /** Show the settings in force, and put them back in the form as unchanged; after a save (`sent` the form as
453	   * it was saved), a setting changed in the form since is left as it was typed. */
454	  private showSettings(s: SheetSettings, sent?: SettingsFormValue): void {
455	    this.settings.set(s);
456	    this.floor.set(s.floor);
457	    this.latePct.set(s.latePct);
458	    this.policyDate.set(s.policyDate);
459	    const shown: SettingsFormValue = {
460	      clerkLimit: s.clerkLimit ?? '',
461	      floor: s.floor,
462	      terms: String(s.terms),
463	      termsA: s.termsA === null ? '' : String(s.termsA),
464	      termsB: s.termsB === null ? '' : String(s.termsB),
465	      termsC: s.termsC === null ? '' : String(s.termsC),
466	      latePct: s.latePct,
467	      policyDate: s.policyDate ?? '',
468	      periodNumberingFrom: s.periodNumberingFrom ?? '',
469	    };
470	    const controls = this.settingsForm.controls;
471	    for (const key of Object.keys(shown) as (keyof SettingsFormValue)[]) {
472	      if (!sent || controls[key].value === sent[key]) controls[key].reset(shown[key], { emitEvent: false });
473	    }
474	  }
475	}
