520	    /** The role a user name has on the sheet: a clerk unless given another. */
521	    @Transactional(readOnly = true)
522	    public Role roleOf(String sheetId, String user) {
523	        return roles.findBySheetIdAndUser(sheetId, user).map(SheetRole::getRole).orElse(Role.CLERK);
524	    }
