526	    /** Give a user name a role on the sheet, replacing any it had. */
527	    @Transactional
528	    public SheetRole setRole(String user, String sheetId, String name, Role role) {
529	        sheets.lock(sheetId);
530	        SheetRole given = roles.findBySheetIdAndUser(sheetId, name).orElse(null);
531	        if (given == null) {
532	            given = roles.saveAndFlush(new SheetRole(sheetId, name, role));
533	        } else {
534	            given.setRole(role);
535	            roles.flush();
536	        }
537	        audit.recordOnCommit("ROLE_SET sheet=" + sheetId + " by=" + user + " user=" + name + " role=" + role.code());
538	        return given;
539	    }
540	
541	    /** Save the settings given, the clerk limit, the floor, the terms, each grade's terms (in the order given),
542	     * the late percent then the policy date, and the period numbering date together; a setting not given (null)
543	     * is left as it is, and an empty clerk limit, grade's terms, policy date or period numbering date removes it. */
544	    @Transactional
545	    public void save(String user, String sheetId, Optional<BigDecimal> clerkLimit, BigDecimal floor,
546	            Integer terms, Map<String, Optional<Integer>> gradeTerms, BigDecimal latePct,
547	            Optional<LocalDate> policyDate, Optional<LocalDate> periodNumberingFrom) {
548	        if (clerkLimit != null) {
549	            setClerkLimit(user, sheetId, clerkLimit.orElse(null));
550	        }
551	        if (floor != null) {
552	            setFloor(user, sheetId, floor);
553	        }
554	        if (terms != null) {
555	            setTerms(user, sheetId, terms);
556	        }
557	        gradeTerms.forEach((grade, days) -> setGradeTerms(user, sheetId, grade, days.orElse(null)));
558	        if (latePct != null) {
559	            setLatePct(user, sheetId, latePct);
560	        }
561	        if (policyDate != null) {
562	            setPolicyDate(user, sheetId, policyDate.orElse(null));
563	        }
564	        if (periodNumberingFrom != null) {
565	            setPeriodNumberingFrom(user, sheetId, periodNumberingFrom.orElse(null));
566	        }
567	    }
