import { HttpClient } from '@angular/common/http';
import { Injectable, inject } from '@angular/core';
import { Observable } from 'rxjs';
import { Session } from '../../core/session';

/** The roles a user name can have on a sheet; any name without one is a clerk. */
export const ROLES = ['clerk', 'steward'] as const;
export type Role = (typeof ROLES)[number];

export interface RoleGiven {
  user: string;
  role: Role;
}

export interface Settings {
  /** The highest due a clerk may settle, with two decimals; null for no limit. */
  clerkLimit: string | null;
  /** The least a claim's live due comes to, with two decimals. */
  floor: string;
  /** The days after its date a claim is due by. */
  terms: number;
  /** Each grade's own terms in days; null when the grade uses the sheet's terms. */
  termsA: number | null;
  termsB: number | null;
  termsC: number | null;
  /** What an overdue claim gains of its figure for every full 30 days overdue, with two decimals. */
  latePct: string;
  /** The date (yyyy-mm-dd) a claim dated before rounds half up, on or after half to even; null for the
   * sheet's today. */
  policyDate: string | null;
  /** The date (yyyy-mm-dd) from which, while the sheet's today is on or after it, a claim opened is numbered
   * within its period; null when off. */
  periodNumberingFrom: string | null;
}

// A sheet's settings: the role each user name has, its clerk limit, its floor, its terms and each grade's, its late percent and its policy date, read and changed through the
// server.
@Injectable({ providedIn: 'root' })
export class SettingsApi {
  private readonly http = inject(HttpClient);
  private readonly session = inject(Session);

  roles(sheetId: string): Observable<RoleGiven[]> {
    return this.http.get<RoleGiven[]>(`${this.url(sheetId)}/roles`, { headers: this.headers() });
  }

  setRole(sheetId: string, user: string, role: string): Observable<RoleGiven> {
    return this.http.put<RoleGiven>(`${this.url(sheetId)}/roles`, { user, role }, { headers: this.headers() });
  }

  get(sheetId: string): Observable<Settings> {
    return this.http.get<Settings>(`${this.url(sheetId)}/settings`, { headers: this.headers() });
  }

  /** Save the settings given; one left out is left as it is. */
  save(
    sheetId: string,
    settings: { clerkLimit?: string; floor?: string; terms?: string; termsA?: string; termsB?: string;
      termsC?: string; latePct?: string; policyDate?: string; periodNumberingFrom?: string; },
  ): Observable<Settings> {
    return this.http.put<Settings>(`${this.url(sheetId)}/settings`, settings, { headers: this.headers() });
  }

  private url(sheetId: string): string {
    return `/api/sheets/${encodeURIComponent(sheetId)}`;
  }

  private headers(): Record<string, string> {
    return { 'X-User': this.session.user() ?? '' };
  }
}
import { Injectable, signal } from '@angular/core';

/** The late percent a sheet starts with. */
export const DEFAULT_LATE_PCT = '0.00';

// The active sheet's late percent, what an overdue claim gains of its figure for every full 30 days it is
// overdue: set by the settings when they are read or saved, and read wherever a due is shown.
@Injectable({ providedIn: 'root' })
export class SheetLatePct {
  private readonly _value = signal(DEFAULT_LATE_PCT);
  readonly value = this._value.asReadonly();

  set(latePct: string): void {
    this._value.set(latePct);
  }
}
import { Injectable, signal } from '@angular/core';

/** The floor a sheet starts with. */
export const DEFAULT_FLOOR = '1.00';

// The active sheet's floor, the least a claim's live due comes to: set by the settings when they are read
// or saved, and read wherever a due is shown.
@Injectable({ providedIn: 'root' })
export class SheetFloor {
  private readonly _value = signal(DEFAULT_FLOOR);
  readonly value = this._value.asReadonly();

  set(floor: string): void {
    this._value.set(floor);
  }
}
import { Component, DestroyRef, inject, signal } from '@angular/core';
import { toObservable } from '@angular/core/rxjs-interop';
import { FormControl, FormGroup, ReactiveFormsModule } from '@angular/forms';
import { Subject, catchError, concatMap, forkJoin, map, of, switchMap } from 'rxjs';
import { Session } from '../../core/session';
import { ROLES, RoleGiven, Settings as SheetSettings, SettingsApi } from './settings-api';
import { DEFAULT_FLOOR, SheetFloor } from './sheet-floor';
import { DEFAULT_LATE_PCT, SheetLatePct } from './sheet-late-pct';
import { SheetPolicyDate } from './sheet-policy-date';

/** The terms a sheet starts with, in days. */
const DEFAULT_TERMS = 14;
/** The grades that can have terms of their own. */
const GRADES = ['A', 'B', 'C'] as const;
type GradeTermsKey = `terms${(typeof GRADES)[number]}`;
const LIMIT = /^\d{1,10}(\.\d{1,2})?$/;
const DAYS = /^\d{1,5}$/;
const PCT = /^\d{1,5}(\.\d{1,2})?$/;
const DATE = /^\d{4}-\d{2}-\d{2}$/;
type SettingsFormValue = {
  clerkLimit: string;
  floor: string;
  terms: string;
  termsA: string;
  termsB: string;
  termsC: string;
  latePct: string;
  policyDate: string;
  periodNumberingFrom: string;
};

const NO_SETTINGS: SheetSettings = {
  clerkLimit: null,
  floor: DEFAULT_FLOOR,
  terms: DEFAULT_TERMS,
  termsA: null,
  termsB: null,
  termsC: null,
  latePct: DEFAULT_LATE_PCT,
  policyDate: null,
  periodNumberingFrom: null,
};

// The sheet's settings: the role each user name has (clerk unless given another) with the form that
// gives one, the clerk limit, the highest due a clerk may settle (blank for no limit), and the floor, the
// least a claim's live due comes to, the terms, the days after its date a claim is due by (fixed when it is
// added), and each grade's own terms (blank for the sheet's), and the late
// percent, what an overdue claim gains of its figure for every full 30 days overdue, and the policy date (blank
// for the sheet's today), before which a claim's date rounds half up, on or after half to even, and the period
// numbering date (blank for off), from which a claim opened is numbered within its period. Saving sends
// only the settings changed in the form (the clerk limit when none was).
@Component({
  selector: 'app-settings',
  imports: [ReactiveFormsModule],
  template: `
    <section aria-labelledby="settings-heading" data-testid="settings">
      <h2 id="settings-heading">Settings</h2>
      <form [formGroup]="settingsForm" (ngSubmit)="save()" (focusin)="focused($event)" data-testid="settings-form">
        <label for="setting-clerk-limit">Clerk limit (blank for none)</label>
        <input
          id="setting-clerk-limit"
          data-testid="setting-clerk-limit"
          inputmode="decimal"
          formControlName="clerkLimit"
        />
        <label for="setting-floor">Floor</label>
        <input id="setting-floor" data-testid="setting-floor" inputmode="decimal" formControlName="floor" />
        <label for="setting-terms">Terms (days)</label>
        <input id="setting-terms" data-testid="setting-terms" inputmode="numeric" formControlName="terms" />
        @for (g of grades; track g) {
          <label [for]="'setting-terms-' + g">Terms for grade {{ g }} (days, blank for the sheet's)</label>
          <input
            [id]="'setting-terms-' + g"
            [attr.data-testid]="'setting-terms-' + g"
            inputmode="numeric"
            [formControlName]="'terms' + g"
          />
        }
        <label for="setting-late-pct">Late percent (per full 30 days overdue)</label>
        <input id="setting-late-pct" data-testid="setting-late-pct" inputmode="decimal" formControlName="latePct" />
        <label for="setting-policy-date">Policy date (yyyy-mm-dd, blank for the sheet's today)</label>
        <input id="setting-policy-date" data-testid="setting-policy-date" formControlName="policyDate" />
        <label for="setting-period-numbering-from">Period numbering from (yyyy-mm-dd, blank for off)</label>
        <input
          id="setting-period-numbering-from"
          data-testid="setting-period-numbering-from"
          formControlName="periodNumberingFrom"
        />
        <button type="submit" data-testid="settings-save">Save settings</button>
      </form>
      @if (settingsError(); as e) {
        <p role="alert" data-testid="settings-error">{{ e }}</p>
      }
      <p>
        Clerk limit in force:
        <span data-testid="setting-clerk-limit-current">{{ settings().clerkLimit ?? '' }}</span>
      </p>
      <p>
        Floor in force:
        <span data-testid="setting-floor-current">{{ settings().floor }}</span>
      </p>
      <p>
        Terms in force:
        <span data-testid="setting-terms-current">{{ settings().terms }}</span>
      </p>
      @for (g of grades; track g) {
        <p>
          Terms for grade {{ g }} in force:
          <span [attr.data-testid]="'setting-terms-' + g + '-current'">{{ settings()[gradeKey(g)] ?? '' }}</span>
        </p>
      }
      <p>
        Late percent in force:
        <span data-testid="setting-late-pct-current">{{ settings().latePct }}</span>
      </p>
      <p>
        Policy date in force:
        <span data-testid="setting-policy-date-current">{{ settings().policyDate ?? '' }}</span>
      </p>
      <p>
        Period numbering from:
        <span data-testid="setting-period-numbering-from-current">{{ settings().periodNumberingFrom ?? '' }}</span>
      </p>
      <form [formGroup]="roleForm" (ngSubmit)="setRole()" data-testid="role-form">
        <label for="role-form-user">User</label>
        <input id="role-form-user" data-testid="role-form-user" formControlName="user" />
        <label for="role-form-role">Role ({{ roleNames }})</label>
        <input id="role-form-role" data-testid="role-form-role" formControlName="role" />
        <button type="submit" data-testid="role-form-submit">Set role</button>
      </form>
      @if (roleError(); as e) {
        <p role="alert" data-testid="role-form-error">{{ e }}</p>
      }
      <table data-testid="role-list">
        <caption>Roles (anyone else is a clerk)</caption>
        <thead>
          <tr>
            <th scope="col">User</th>
            <th scope="col">Role</th>
          </tr>
        </thead>
        <tbody>
          @for (r of roles(); track r.user) {
            <tr [attr.data-testid]="'role-row-' + r.user">
              <td data-testid="role-user">{{ r.user }}</td>
              <td data-testid="role-value">{{ r.role }}</td>
            </tr>
          }
        </tbody>
      </table>
    </section>
  `,
})
export class Settings {
  private readonly session = inject(Session);
  private readonly api = inject(SettingsApi);
  private readonly floor = inject(SheetFloor);
  private readonly latePct = inject(SheetLatePct);
  private readonly policyDate = inject(SheetPolicyDate);

  protected readonly roleNames = ROLES.join(' or ');
  protected readonly grades = GRADES;
  protected readonly roles = signal<RoleGiven[]>([]);
  protected readonly settings = signal<SheetSettings>(NO_SETTINGS);
  protected readonly roleError = signal<string | null>(null);
  protected readonly settingsError = signal<string | null>(null);
  private readonly busy = signal(false);
  /** The setting a person went into last; the clerk limit until they go into one. */
  private lastField: keyof SettingsFormValue = 'clerkLimit';
  /** Settings saves, sent one after another in the order they were made, so none is lost while another is
   * waiting on the server. */
  private readonly saves = new Subject<{ sheetId: string; changed: Parameters<SettingsApi['save']>[1]; sent: SettingsFormValue }>();
  protected readonly roleForm = new FormGroup({
    user: new FormControl('', { nonNullable: true }),
    role: new FormControl('', { nonNullable: true }),
  });
  protected readonly settingsForm = new FormGroup({
    clerkLimit: new FormControl('', { nonNullable: true }),
    floor: new FormControl(DEFAULT_FLOOR, { nonNullable: true }),
    terms: new FormControl(String(DEFAULT_TERMS), { nonNullable: true }),
    termsA: new FormControl('', { nonNullable: true }),
    termsB: new FormControl('', { nonNullable: true }),
    termsC: new FormControl('', { nonNullable: true }),
    latePct: new FormControl(DEFAULT_LATE_PCT, { nonNullable: true }),
    policyDate: new FormControl('', { nonNullable: true }),
    periodNumberingFrom: new FormControl('', { nonNullable: true }),
  });

  constructor() {
    this.roleForm.valueChanges.subscribe(() => this.roleError.set(null));
    this.settingsForm.valueChanges.subscribe(() => this.settingsError.set(null));
    this.saves
      .pipe(
        concatMap(({ sheetId, changed, sent }) =>
          this.api.save(sheetId, changed).pipe(
            map((s) => ({ sheetId, sent, s })),
            catchError(() => of({ sheetId, sent, s: null })),
          ),
        ),
      )
      .subscribe(({ sheetId, sent, s }) => {
        if (s === null) {
          this.settingsError.set('Could not save the settings.');
        } else if (this.session.sheetId() === sheetId) {
          this.showSettings(s, sent);
        }
      });
    // Re-read the sheet's settings from the store each time a sheet is loaded.
    const loaded = this.session.registerLoader(inject(DestroyRef));
    toObservable(this.session.sheetId)
      .pipe(
        switchMap((id) =>
          id
            ? forkJoin({ id: of(id), roles: this.api.roles(id), settings: this.api.get(id) })
            : of({ id, roles: [] as RoleGiven[], settings: NO_SETTINGS }),
        ),
      )
      .subscribe(({ id, roles, settings }) => {
        this.roles.set(roles);
        this.showSettings(settings);
        this.roleError.set(null);
        this.settingsError.set(null);
        loaded(id);
      });
  }

  protected setRole(): void {
    if (this.busy()) return;
    this.roleError.set(null);
    const sheetId = this.session.sheetId();
    if (!sheetId) {
      this.roleError.set('Load a sheet first.');
      return;
    }
    const user = this.roleForm.getRawValue().user.trim();
    const role = this.roleForm.getRawValue().role.trim();
    if (!user) {
      this.roleError.set('Type a user name.');
      return;
    }
    if (!(ROLES as readonly string[]).includes(role)) {
      this.roleError.set(`A role is ${this.roleNames}.`);
      return;
    }
    this.busy.set(true);
    this.api.setRole(sheetId, user, role).subscribe({
      next: (given) => {
        this.busy.set(false);
        if (this.session.sheetId() !== sheetId) return;
        this.roles.update((rs) =>
          rs.some((r) => r.user === given.user)
            ? rs.map((r) => (r.user === given.user ? given : r))
            : [...rs, given],
        );
        this.roleForm.reset({ user: '', role: '' }, { emitEvent: false });
      },
      error: () => {
        this.busy.set(false);
        this.roleError.set('Could not set that role.');
      },
    });
  }

  /** The setting holding a grade's own terms. */
  protected gradeKey(grade: (typeof GRADES)[number]): GradeTermsKey {
    return `terms${grade}`;
  }

  /** Note the setting a person went into last: a save with nothing changed saves that one again. */
  protected focused(event: FocusEvent): void {
    const name = (event.target as Element | null)?.getAttribute('formcontrolname');
    if (name && name in this.settingsForm.controls) this.lastField = name as keyof SettingsFormValue;
  }

  protected save(): void {
    this.settingsError.set(null);
    const sheetId = this.session.sheetId();
    if (!sheetId) {
      this.settingsError.set('Load a sheet first.');
      return;
    }
    const controls = this.settingsForm.controls;
    // With nothing changed, the setting last gone into is saved again as it is.
    const unchanged = !this.settingsForm.dirty;
    const send = (key: keyof SettingsFormValue) => controls[key].dirty || (unchanged && this.lastField === key);
    const clerkLimit = controls.clerkLimit.value.trim();
    const floor = controls.floor.value.trim();
    const terms = controls.terms.value.trim();
    const sendFloor = send('floor');
    const latePct = controls.latePct.value.trim();
    const sendTerms = send('terms');
    const sendLatePct = send('latePct');
    const policyDate = controls.policyDate.value.trim();
    const sendPolicyDate = send('policyDate');
    const periodNumberingFrom = controls.periodNumberingFrom.value.trim();
    const sendPeriodNumbering = send('periodNumberingFrom');
    const sendLimit = send('clerkLimit');
    if (sendLimit && clerkLimit !== '' && !LIMIT.test(clerkLimit)) {
      this.settingsError.set('Type a clerk limit of 0.00 or more, with up to two decimals, or leave it blank.');
      return;
    }
    if (sendFloor && !LIMIT.test(floor)) {
      this.settingsError.set('Type a floor of 0.00 or more, with up to two decimals.');
      return;
    }
    if (sendTerms && !DAYS.test(terms)) {
      this.settingsError.set('Type terms of 0 or more whole days.');
      return;
    }
    const gradeTerms: Partial<Record<GradeTermsKey, string>> = {};
    for (const g of GRADES) {
      const key = this.gradeKey(g);
      if (!send(key)) continue;
      const days = controls[key].value.trim();
      if (days !== '' && !DAYS.test(days)) {
        this.settingsError.set(`Type terms for grade ${g} of 0 or more whole days, or leave them blank.`);
        return;
      }
      gradeTerms[key] = days;
    }
    if (sendLatePct && !PCT.test(latePct)) {
      this.settingsError.set('Type a late percent of 0.00 or more, with up to two decimals.');
      return;
    }
    if (sendPolicyDate && policyDate !== '' && !(DATE.test(policyDate) && !isNaN(Date.parse(policyDate)))) {
      this.settingsError.set('Type a policy date as yyyy-mm-dd, or leave it blank.');
      return;
    }
    if (
      sendPeriodNumbering &&
      periodNumberingFrom !== '' &&
      !(DATE.test(periodNumberingFrom) && !isNaN(Date.parse(periodNumberingFrom)))
    ) {
      this.settingsError.set('Type a period numbering date as yyyy-mm-dd, or leave it blank.');
      return;
    }
    const changed = {
      ...(sendLimit ? { clerkLimit } : {}),
      ...(sendFloor ? { floor } : {}),
      ...(sendTerms ? { terms } : {}),
      ...gradeTerms,
      ...(sendLatePct ? { latePct } : {}),
      ...(sendPolicyDate ? { policyDate } : {}),
      ...(sendPeriodNumbering ? { periodNumberingFrom } : {}),
    };
    this.saves.next({ sheetId, changed, sent: this.settingsForm.getRawValue() });
  }

  /** Show the settings in force, and put them back in the form as unchanged; after a save (`sent` the form as
   * it was saved), a setting changed in the form since is left as it was typed. */
  private showSettings(s: SheetSettings, sent?: SettingsFormValue): void {
    this.settings.set(s);
    this.floor.set(s.floor);
    this.latePct.set(s.latePct);
    this.policyDate.set(s.policyDate);
    const shown: SettingsFormValue = {
      clerkLimit: s.clerkLimit ?? '',
      floor: s.floor,
      terms: String(s.terms),
      termsA: s.termsA === null ? '' : String(s.termsA),
      termsB: s.termsB === null ? '' : String(s.termsB),
      termsC: s.termsC === null ? '' : String(s.termsC),
      latePct: s.latePct,
      policyDate: s.policyDate ?? '',
      periodNumberingFrom: s.periodNumberingFrom ?? '',
    };
    const controls = this.settingsForm.controls;
    for (const key of Object.keys(shown) as (keyof SettingsFormValue)[]) {
      if (!sent || controls[key].value === sent[key]) controls[key].reset(shown[key], { emitEvent: false });
    }
  }
}
package net.officefloor.hq.app.setting;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.List;
import java.util.Map;
import java.util.Optional;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.rollup.RollupService;
import net.officefloor.hq.app.rollup.RollupService.Snapshot;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.hq.app.sheet.SheetService;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;

/** A sheet's settings: the role each user name has on it, its clerk limit, its floor, its terms, its late percent, its policy date and its period numbering date. */
@Service
public class SettingService {

    private final SheetRoleRepository roles;
    private final SheetRepository sheetRepository;
    private final SheetService sheets;
    private final RollupService rollup;
    private final Audit audit;

    public SettingService(SheetRoleRepository roles, SheetRepository sheetRepository, SheetService sheets,
            RollupService rollup, Audit audit) {
        this.roles = roles;
        this.sheetRepository = sheetRepository;
        this.sheets = sheets;
        this.rollup = rollup;
        this.audit = audit;
    }

    /** The roles given on the sheet. */
    @Transactional(readOnly = true)
    public List<SheetRole> roles(String sheetId) {
        sheets.today(sheetId); // the sheet must exist
        return roles.findBySheetIdOrderById(sheetId);
    }

    /** The role a user name has on the sheet: a clerk unless given another. */
    @Transactional(readOnly = true)
    public Role roleOf(String sheetId, String user) {
        return roles.findBySheetIdAndUser(sheetId, user).map(SheetRole::getRole).orElse(Role.CLERK);
    }

    /** Give a user name a role on the sheet, replacing any it had. */
    @Transactional
    public SheetRole setRole(String user, String sheetId, String name, Role role) {
        sheets.lock(sheetId);
        SheetRole given = roles.findBySheetIdAndUser(sheetId, name).orElse(null);
        if (given == null) {
            given = roles.saveAndFlush(new SheetRole(sheetId, name, role));
        } else {
            given.setRole(role);
            roles.flush();
        }
        audit.recordOnCommit("ROLE_SET sheet=" + sheetId + " by=" + user + " user=" + name + " role=" + role.code());
        return given;
    }

    /** Save the settings given, the clerk limit, the floor, the terms, each grade's terms (in the order given),
     * the late percent then the policy date, and the period numbering date together; a setting not given (null)
     * is left as it is, and an empty clerk limit, grade's terms, policy date or period numbering date removes it. */
    @Transactional
    public void save(String user, String sheetId, Optional<BigDecimal> clerkLimit, BigDecimal floor,
            Integer terms, Map<String, Optional<Integer>> gradeTerms, BigDecimal latePct,
            Optional<LocalDate> policyDate, Optional<LocalDate> periodNumberingFrom) {
        if (clerkLimit != null) {
            setClerkLimit(user, sheetId, clerkLimit.orElse(null));
        }
        if (floor != null) {
            setFloor(user, sheetId, floor);
        }
        if (terms != null) {
            setTerms(user, sheetId, terms);
        }
        gradeTerms.forEach((grade, days) -> setGradeTerms(user, sheetId, grade, days.orElse(null)));
        if (latePct != null) {
            setLatePct(user, sheetId, latePct);
        }
        if (policyDate != null) {
            setPolicyDate(user, sheetId, policyDate.orElse(null));
        }
        if (periodNumberingFrom != null) {
            setPeriodNumberingFrom(user, sheetId, periodNumberingFrom.orElse(null));
        }
    }

    /** The sheet's clerk limit; none means no limit. */
    @Transactional(readOnly = true)
    public BigDecimal clerkLimit(String sheetId) {
        return find(sheetId).getClerkLimit();
    }

    /** Set the sheet's clerk limit; none removes it. */
    @Transactional
    public BigDecimal setClerkLimit(String user, String sheetId, BigDecimal limit) {
        sheets.lock(sheetId);
        Sheet sheet = find(sheetId);
        BigDecimal value = limit != null ? limit.setScale(2) : null;
        sheet.setClerkLimit(value);
        sheetRepository.flush();
        audit.recordOnCommit("SETTING_CHANGED sheet=" + sheetId + " by=" + user + " key=clerk-limit value="
                + (value != null ? value.toPlainString() : ""));
        return value;
    }

    /** The sheet's floor: the least a claim's live due comes to. */
    @Transactional(readOnly = true)
    public BigDecimal floor(String sheetId) {
        return find(sheetId).getFloor();
    }

    /** Set the sheet's floor; it moves every live due below it, and the figures it moves are written after. */
    @Transactional
    public BigDecimal setFloor(String user, String sheetId, BigDecimal floor) {
        sheets.lock(sheetId);
        Sheet sheet = find(sheetId);
        Snapshot before = rollup.snapshot(sheetId);
        BigDecimal value = floor.setScale(2);
        sheet.setFloor(value);
        sheetRepository.flush();
        audit.recordOnCommit("SETTING_CHANGED sheet=" + sheetId + " by=" + user + " key=floor value="
                + value.toPlainString());
        rollup.recordChanges(user, sheetId, before);
        return value;
    }

    /** The sheet's terms: the days after its date a claim is due by. */
    @Transactional(readOnly = true)
    public int terms(String sheetId) {
        return find(sheetId).getTerms();
    }

    /** Set the sheet's terms; they go for claims added from now on (a claim's due-by is fixed when it is added),
     * so they move no figure. */
    @Transactional
    public int setTerms(String user, String sheetId, int terms) {
        sheets.lock(sheetId);
        Sheet sheet = find(sheetId);
        sheet.setTerms(terms);
        sheetRepository.flush();
        audit.recordOnCommit("SETTING_CHANGED sheet=" + sheetId + " by=" + user + " key=terms value=" + terms);
        return terms;
    }

    /** A grade's own terms; none when it uses the sheet's. */
    @Transactional(readOnly = true)
    public Integer gradeTerms(String sheetId, String grade) {
        return find(sheetId).getGradeTerms(grade);
    }

    /** Set a grade's own terms, none to have it use the sheet's; like the sheet's terms they go for claims added
     * from now on. */
    @Transactional
    public Integer setGradeTerms(String user, String sheetId, String grade, Integer terms) {
        sheets.lock(sheetId);
        Sheet sheet = find(sheetId);
        sheet.setGradeTerms(grade, terms);
        sheetRepository.flush();
        audit.recordOnCommit("SETTING_CHANGED sheet=" + sheetId + " by=" + user + " key=terms-" + grade + " value="
                + (terms != null ? terms.toString() : ""));
        return terms;
    }

    /** The terms in force for a claim of a person of the grade: the grade's own, else the sheet's. */
    @Transactional(readOnly = true)
    public int termsFor(String sheetId, String grade) {
        return find(sheetId).termsFor(grade);
    }

    /** The sheet's late percent: what an overdue claim gains of its figure for every full 30 days overdue. */
    @Transactional(readOnly = true)
    public BigDecimal latePct(String sheetId) {
        return find(sheetId).getLatePct();
    }

    /** Set the sheet's late percent; it moves every late charge, and the figures it moves are written after. */
    @Transactional
    public BigDecimal setLatePct(String user, String sheetId, BigDecimal latePct) {
        sheets.lock(sheetId);
        Sheet sheet = find(sheetId);
        Snapshot before = rollup.snapshot(sheetId);
        BigDecimal value = latePct.setScale(2);
        sheet.setLatePct(value);
        sheetRepository.flush();
        audit.recordOnCommit("SETTING_CHANGED sheet=" + sheetId + " by=" + user + " key=late-pct value="
                + value.toPlainString());
        rollup.recordChanges(user, sheetId, before);
        return value;
    }

    /** The sheet's policy date: a claim dated before it rounds half up, one dated on or after it half to even;
     * none means the sheet's today. */
    @Transactional(readOnly = true)
    public LocalDate policyDate(String sheetId) {
        return find(sheetId).getPolicyDate();
    }

    /** Set the sheet's policy date, none for the sheet's today; it moves how live figures round, and the figures
     * it moves are written after. */
    @Transactional
    public LocalDate setPolicyDate(String user, String sheetId, LocalDate policyDate) {
        sheets.lock(sheetId);
        Sheet sheet = find(sheetId);
        Snapshot before = rollup.snapshot(sheetId);
        sheet.setPolicyDate(policyDate);
        sheetRepository.flush();
        audit.recordOnCommit("SETTING_CHANGED sheet=" + sheetId + " by=" + user + " key=policy-date value="
                + (policyDate != null ? policyDate.toString() : ""));
        rollup.recordChanges(user, sheetId, before);
        return policyDate;
    }

    /** The sheet's period numbering date: while the sheet's today is on or after it, a claim opened is numbered
     * within its period; none means off. */
    @Transactional(readOnly = true)
    public LocalDate periodNumberingFrom(String sheetId) {
        return find(sheetId).getPeriodNumberingFrom();
    }

    /** Set the sheet's period numbering date, none to turn it off; it numbers only claims opened from now on. */
    @Transactional
    public LocalDate setPeriodNumberingFrom(String user, String sheetId, LocalDate from) {
        sheets.lock(sheetId);
        Sheet sheet = find(sheetId);
        sheet.setPeriodNumberingFrom(from);
        sheetRepository.flush();
        audit.recordOnCommit("SETTING_CHANGED sheet=" + sheetId + " by=" + user + " key=period-numbering-from value="
                + (from != null ? from.toString() : ""));
        return from;
    }

    /** Whether a user may settle a claim of this due outright: a due of n/a is within any limit, and a steward
     * settles anything; a clerk's settle above the clerk limit goes to a steward instead. */
    @Transactional(readOnly = true)
    public boolean maySettle(String sheetId, String user, BigDecimal due) {
        BigDecimal limit = clerkLimit(sheetId);
        return limit == null || due == null || due.compareTo(limit) <= 0 || roleOf(sheetId, user) == Role.STEWARD;
    }

    /** Refuse a change only a steward may make, such as approving or rejecting a PENDING claim. */
    @Transactional(readOnly = true)
    public void requireSteward(String sheetId, String user) {
        if (roleOf(sheetId, user) != Role.STEWARD) {
            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT, "Only a steward can do that.");
        }
    }

    private Sheet find(String sheetId) {
        return sheetRepository.findById(sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such sheet."));
    }
}
package net.officefloor.hq.app.setting;

import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Pattern;
import jakarta.validation.constraints.Size;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Optional;
import org.springframework.http.HttpStatus;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PutMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;
import org.springframework.web.server.ResponseStatusException;

/** A sheet's settings: the role each user name has, its clerk limit, its floor, its terms, its late percent, its policy date and its period numbering date. */
@RestController
@RequestMapping("/api/sheets/{sheetId}")
public class SettingController {

    /** The role is clerk or steward. */
    public record RoleForm(@NotBlank @Size(max = 100) String user, @NotNull String role) {}

    public record RoleView(String user, String role) {

        static RoleView of(SheetRole role) {
            return new RoleView(role.getUser(), role.getRole().code());
        }
    }

    /** The clerk limit has up to two decimals, 0.00 or more; blank means no limit. The floor has up to two
     * decimals, 0.00 or more. The terms are a whole number of days, 0 or more; so are each grade's terms, where
     * blank means the grade uses the sheet's terms. The late percent has up to two
     * decimals, 0.00 or more. The policy date is a date (yyyy-mm-dd); blank means the sheet's today. The period numbering date is a date; blank means
     * off. A setting
     * left out (null) is left as it is. */
    public record SettingsForm(@Pattern(regexp = "|\\d{1,10}(\\.\\d{1,2})?") String clerkLimit,
            @Pattern(regexp = "\\d{1,10}(\\.\\d{1,2})?") String floor,
            @Pattern(regexp = "\\d{1,5}") String terms,
            @Pattern(regexp = "|\\d{1,5}") String termsA,
            @Pattern(regexp = "|\\d{1,5}") String termsB,
            @Pattern(regexp = "|\\d{1,5}") String termsC,
            @Pattern(regexp = "\\d{1,5}(\\.\\d{1,2})?") String latePct,
            @Pattern(regexp = "|\\d{4}-\\d{2}-\\d{2}") String policyDate,
            @Pattern(regexp = "|\\d{4}-\\d{2}-\\d{2}") String periodNumberingFrom) {}

    /** The clerk limit and floor are shown with two decimals; the clerk limit is null when there is none. The
     * terms are the days after its date a claim is due by; each grade's terms are null when it uses the sheet's. The late percent is shown with two decimals. The policy date is null when there is none (the sheet's
     * today is used). The period numbering date is null when it is off. */
    public record SettingsView(String clerkLimit, String floor, int terms, Integer termsA, Integer termsB,
            Integer termsC, String latePct, String policyDate, String periodNumberingFrom) {

        static SettingsView of(BigDecimal clerkLimit, BigDecimal floor, int terms, Integer termsA, Integer termsB,
                Integer termsC, BigDecimal latePct, LocalDate policyDate, LocalDate periodNumberingFrom) {
            return new SettingsView(clerkLimit != null ? clerkLimit.setScale(2).toPlainString() : null,
                    floor.setScale(2).toPlainString(), terms, termsA, termsB, termsC,
                    latePct.setScale(2).toPlainString(),
                    policyDate != null ? policyDate.toString() : null,
                    periodNumberingFrom != null ? periodNumberingFrom.toString() : null);
        }
    }

    private final SettingService service;

    public SettingController(SettingService service) {
        this.service = service;
    }

    @GetMapping("/roles")
    public List<RoleView> roles(@RequestHeader("X-User") String user, @PathVariable String sheetId) {
        return service.roles(sheetId).stream().map(RoleView::of).toList();
    }

    @PutMapping("/roles")
    public RoleView setRole(@RequestHeader("X-User") String user, @PathVariable String sheetId,
            @Valid @RequestBody RoleForm form) {
        Role role = Role.of(form.role().trim()).orElseThrow(
                () -> new ResponseStatusException(HttpStatus.BAD_REQUEST, "A role is clerk or steward."));
        return RoleView.of(service.setRole(user, sheetId, form.user().trim(), role));
    }

    @GetMapping("/settings")
    public SettingsView settings(@RequestHeader("X-User") String user, @PathVariable String sheetId) {
        return view(sheetId);
    }

    @PutMapping("/settings")
    public SettingsView save(@RequestHeader("X-User") String user, @PathVariable String sheetId,
            @Valid @RequestBody SettingsForm form) {
        String limit = form.clerkLimit();
        Optional<BigDecimal> clerkLimit = limit == null ? null
                : limit.isEmpty() ? Optional.empty() : Optional.of(new BigDecimal(limit));
        Optional<LocalDate> policyDate = dateOrBlank(form.policyDate(), "A policy date is a date, or blank.");
        Optional<LocalDate> periodNumberingFrom = dateOrBlank(form.periodNumberingFrom(),
                "A period numbering date is a date, or blank.");
        service.save(user, sheetId, clerkLimit, form.floor() == null ? null : new BigDecimal(form.floor()),
                form.terms() == null ? null : Integer.valueOf(form.terms()), gradeTerms(form),
                form.latePct() == null ? null : new BigDecimal(form.latePct()), policyDate, periodNumberingFrom);
        return view(sheetId);
    }

    private SettingsView view(String sheetId) {
        return SettingsView.of(service.clerkLimit(sheetId), service.floor(sheetId), service.terms(sheetId),
                service.gradeTerms(sheetId, "A"), service.gradeTerms(sheetId, "B"), service.gradeTerms(sheetId, "C"),
                service.latePct(sheetId), service.policyDate(sheetId), service.periodNumberingFrom(sheetId));
    }

    /** The grades' terms given, in grade order: empty when blank (the grade uses the sheet's terms); a grade
     * left out is left as it is. */
    private static Map<String, Optional<Integer>> gradeTerms(SettingsForm form) {
        Map<String, Optional<Integer>> given = new LinkedHashMap<>();
        Map<String, String> typed = new LinkedHashMap<>();
        typed.put("A", form.termsA());
        typed.put("B", form.termsB());
        typed.put("C", form.termsC());
        typed.forEach((grade, days) -> {
            if (days != null) {
                given.put(grade, days.isEmpty() ? Optional.empty() : Optional.of(Integer.valueOf(days)));
            }
        });
        return given;
    }

    /** A date setting as given: null when left out, empty when blank. */
    private static Optional<LocalDate> dateOrBlank(String date, String refusal) {
        try {
            return date == null ? null : date.isEmpty() ? Optional.empty() : Optional.of(LocalDate.parse(date));
        } catch (DateTimeParseException e) {
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, refusal);
        }
    }
}
